import 'package:flutter/material.dart';
import '../services/supabase_service.dart';
class SettingsScreen extends StatelessWidget{const SettingsScreen({super.key});@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Settings')),body:ListView(padding:const EdgeInsets.all(16),children:[const Card(child:ListTile(leading:Icon(Icons.security),title:Text('Account Security'),subtitle:Text('Authentication managed by Supabase'))),const Card(child:ListTile(leading:Icon(Icons.palette),title:Text('Appearance'),subtitle:Text('Dark theme'))),FilledButton.icon(onPressed:()async{await SupabaseService.logout();if(context.mounted)Navigator.pop(context);},icon:const Icon(Icons.logout),label:const Text('Sign Out'),style:FilledButton.styleFrom(backgroundColor:Colors.redAccent))]));}
